+		if err == nil || !strings.Contains(err.Error(), `required material "git+https://github.com/example/other" is not present`) {
+			t.Errorf("Verify() error = %v", err)
+		}
+	})
+
+	t.Run("digest mismatch", func(t *testing.T) {
