+			RequiredMaterials: []Material{{Digest: DigestSet{"sha1": "deadbeef"}}},
+		})
+		if err == nil || !strings.Contains(err.Error(), "empty URI") {
+			t.Errorf("Verify() error = %v", err)
+		}
+	})
+}
